import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))
        s = next(iterator)

        has_clockwise = False
        has_anticlockwise = False

        for char in s:
            if char == '>':
                has_clockwise = True
            elif char == '<':
                has_anticlockwise = True

        if has_clockwise and has_anticlockwise:
            results.append(str(n))
        else:
            count = 0
            for char in s:
                if char == '-':
                    count += 1
            results.append(str(count))

    print('\n'.join(results))

if __name__ == '__main__':
    solve()
